import Model from 'flarum/common/Model';
/** What every review in a category rates 1-5 and comments on. */
export default class Criterion extends Model {
  name = Model.attribute('name');
  weight = Model.attribute('weight');
  position = Model.attribute('position');
  category = Model.hasOne('category');
}
flarum.reg.add('ernestdefoe-community-reviews', 'forum/models/Criterion', Criterion);